const data   = $input.item.json;
const binary = $input.item.binary || {};

// ── 1) externalId : Message-ID sans chevrons ────────────────────────────────
const externalId = (data.messageId || '').replace(/^<|>$/g, '');

// ── 2) referenceCode : extraction du "Réf. NNNN" ────────────────────────────
// Le backend génère "Candidature – {intitule} – Réf. {id:0004}".
// On extrait uniquement le fragment unique.
const refMatch      = (data.subject || '').match(/R[ée]f\.\s*(\d{4,})/i);
const referenceCode = refMatch ? `Réf. ${refMatch[1]}` : null;

// Sujet nettoyé (pour audit/affichage, pas pour matching)
const cleanSubject = (data.subject || '')
  .replace(/^\s*(Re|Fwd?|Tr|TR|FWD|RE)\s*:\s*/gi, '')
  .trim();

// ── 3) Première PJ PDF/DOCX ─────────────────────────────────────────────────
const ALLOWED = ['pdf', 'docx'];
let attachmentKey = null;
for (const [key, file] of Object.entries(binary)) {
  const ext = (file.fileExtension || '').toLowerCase();
  if (ALLOWED.includes(ext)) { attachmentKey = key; break; }
}

// ── 4) Métadonnées audit ────────────────────────────────────────────────────
const fromAddress = data.from?.value?.[0]?.address || '';
const fromName    = data.from?.value?.[0]?.name    || '';
const rawMetadata = JSON.stringify({
  from:       fromAddress,
  fromName,
  subject:    data.subject || '',
  receivedAt: data.date    || null,
});

// ── 5) Output ───────────────────────────────────────────────────────────────
return {
  json: {
    externalId,
    referenceCode,                          // ex: "Réf. 0001" ou null
    subjectClean: cleanSubject,
    senderEmail: fromAddress,
    attachmentKey,
    rawMetadata,
    hasValidAttachment: attachmentKey !== null,
  },
  binary,
};
